="space-y-1 p-2 font-mono text-xs text-[#44474E]">@foreach(($component->definition_json["attributes"] ?? []) as $attribute)<p>{{ $attribute }} <span class="float-right">TEXT</span></p>@endforeach</div></div>@endforeach<div id="book-slot" class="absolute right-6 top-10 flex h-44 w-56 flex-col items-center justify-center rounded-lg bg-[#ECF4FF] text-center">@foreach($puzzle->relations as $relation)<div class="absolute left-1/2 top-[205px] -translate-x-1/2 rounded-full bg-[#69FAD8] px-3 py-1 font-mono text-[11px] font-bold text-[#002019]">{{ $relation->name }} ? {{ data_get($relation->definition_json, "cardinality", "1:N") }}</div>@endforeach<span class="flex h-10 w-10 items-center justify-center rounded-full bg-white text-xl shadow-sm">♢</span><strong class="mt-2 text-[15px]">DROP ZONE: {{ strtoupper($entityNames->get(2, 'KOMPONEN')) }}</strong><small class="mt-1 text-xs text-[#44474E]">Pilih komponen di kanan</small><span class="mt-2 rounded-full bg-[#69FAD8] px-2.5 py-0.5 font-mono text-[11px]">1:N</span></div><span class="absolute left-[25%] top-[205px] rounded bg-white px-2 py-1 font-mono text-xs">meminjam</span><span class="absolute left-[54%] top-[320px] rounded bg-white/80 px-2 py-1 font-mono text-xs text-[#44474E]">tercatat</span></div></section>
<aside class="rounded-xl bg-white p-4 shadow-sm"><h2 class="text-xl font-bold">Komponen Tersisa</h2><p class="mt-1 text-xs leading-4 text-[#44474E]">Seret ke kanvas, atau pilih komponen lalu tekan tombol tempatkan.</p><div class="mt-4 space-y-2">@foreach($puzzle->components as $component)<label draggable="true" tabindex="0" role="button" aria-label="Pilih komponen {{ $component->name }}" data-component="{{ $component->id }}" data-name="{{ $component->name }}" class="erd-component flex cursor-grab items-center justify-between rounded-lg p-3 transition hover:-translate-y-0.5 hover:shadow-sm active:cursor-grabbing focus:outline-none focus:ring-2 focus:ring-[#69FAD8]"><span class="flex items-center gap-2"><span class="font-mono text-lg">?</span><span><strong class="block font-mono text-sm">{{ $component->name }}</strong><small class="text-xs text-[#44474E]">{{ ucfirst($component->type) }}</small></span></span><input type="checkbox" name="components[]" value="{{ $component->id }}" class="h-4 w-4 accent-teal-600"></label>@endforeach</div><button type="button" id="place-erd" class="mt-4 w-full rounded-lg bg-[#000D25] px-4 py-3 text-sm font-semibold text-white">♧ Tempatkan ke slot terpilih</button><div class="mt-4 rounded-lg border-l-4 border-[#006B59] bg-[#ECF4FF] p-3"><h3 class="text-xs font-bold">💡 Petunjuk akademik</h3><p class="mt-2 text-xs leading-5 text-[#44474E]">{{ $puzzle->instructions }}</p></div><div class="mt-4 border-t border-[#D7EAFF] pt-4"><p class="text-sm font-semibold">Pilih relasi</p><div class="mt-2 space-y-2">@foreach($puzzle->relations as $relation)<label class="flex items-center gap-2 text-sm"><input type="checkbox" name="relations[]" value="{{ $relation->id }}" class="h-4 w-4 accent-teal-600">{{ $relation->name }}<select name="relation_cardinality[{{ $relation->id }}]" class="ml-2 rounded border border-slate-200 px-2 py-1 text-xs"><option value="1:N">1:N</option><option value="1:1">1:1</option><option value="N:1">N:1</option><option value="N:M">N:M</option></select></label>@endforeach</div></div></aside><div class="flex items-center justify-between lg:col-span-2"><button type="button" id="clear-erd" class="rounded-lg px-3 py-2 text-sm font-semibold text-[#44474E]">↻ Reset puzzle</button><div class="text-right"><button class="rounded-lg bg-[#000D25] px-8 py-3 text-sm font-semibold text-white">Cek jawaban →</button><p class="mt-1 text-xs text-[#44474E]">Skor lulus minimal 70%</p></div></div></form></div></main><x-student-nav />
<script>const canvas=document.querySelector("#erd-canvas"),slot=document.querySelector("#book-slot"),components=[...document.querySelectorAll(".erd-component")];let placed=null;const render=(name)=>{slot.innerHTML=`<span class="flex h-10 w-10 items-center justify-center rounded-full bg-[#69FAD8] text-xl">?</span><strong class="mt-2 text-[15px]">${name}</strong><small class="mt-1 text-xs text-[#44474E]">Komponen ditempatkan</small><span class="mt-2 rounded-full bg-[#69FAD8] px-2.5 py-0.5 font-mono text-[11px]">1:N</span>`};components.forEach((item)=>{item.addEventListener("dragstart",(e)=>e.dataTransfer.setData("component",item.dataset.name));item.addEventListener("keydown",(e)=>{if(e.key==="Enter"||e.key===" "){e.preventDefault();const input=item.querySelector("input");input.checked=!input.checked;input.dispatchEvent(new Event("change"))}});item.querySelector("input").addEventListener("change",()=>{if(item.querySelector("input").checked){placed=item.dataset.name;render(placed)}})});canvas.addEventListener("dragover",(e)=>{e.preventDefault();canvas.classList.add("ring-4","ring-[#69FAD8]")});canvas.addEventListener("dragleave",()=>canvas.classList.remove("ring-4","ring-[#69FAD8]"));canvas.addEventListener("drop",(e)=>{e.preventDefault();canvas.classList.remove("ring-4","ring-[#69FAD8]");placed=e.dataTransfer.getData("component");const item=components.find((x)=>x.dataset.name===placed);if(item)item.querySelector("input").checked=true;if(placed)render(placed)});document.querySelector("#place-erd")?.addEventListener("click",()=>{const item=components.find((x)=>x.querySelector("input").checked);if(item){placed=item.dataset.name;render(placed)}});document.querySelector("#clear-erd")?.addEventListener("click",()=>{components.forEach((item)=>item.querySelector("input").checked=false);document.querySelectorAll("input[name=relations\\[\\]]").forEach((input)=>input.checked=false);placed=null;slot.innerHTML="<span class=\"flex h-10 w-10 items-center justify-center rounded-full bg-white text-xl shadow-sm\">?</span><strong class=\"mt-2 text-[15px]\">DROP ZONE: KOMPONEN</strong><small class=\"mt-1 text-xs text-[#44474E]\">Pilih komponen di kanan</small><span class=\"mt-2 rounded-full bg-[#69FAD8] px-2.5 py-0.5 font-mono text-[11px]\">1:N</span>"});</script></body></html>